"OLAYLAR_T5_1000B:1154-04-25:0":{"b": ["Nurəddin Zəngi Dəməşqi aldı", "a4fd8b58"], "d": ["Nurəddin Mahmud Dəməşqi hakimiyyəti altına aldı.", "f87fe7de"]},
"OLAYLAR_T5_1000B:1171-09-13:0":{"b": ["Misirdə Fatimi idarəsi sona çatdı, Əyyubilər başa keçdi — İsgəndəriyyə, Feyyum və Məkkə (Hicaz)", "1c565534"], "d": ["Səlahəddinin vəzirliyi və Fatimi xəlifəsi Adidin ölümü ilə (567/1171) Misir Əyyubilərə keçdi; İsgəndəriyyə və Feyyum Əyyubi idarəsinə girdi. Gün mənbədə yoxdur — Fatimi künyəsinin bitişindən götürüldü (künyə günü mənbə deyil). Hicaz da Əyyubi idarəsinə girdi; Məkkənin suzerenliyi Fatimilərdən Əyyubilərə keçdi (Emre #23 suzerenlik modeli).", "191ac5be"]},
"OLAYLAR_T5_1000B:1174-01-01:0":{"b": ["Səlahəddin Dəməşqi aldı", "dfdb11ce"], "d": ["Nurəddinin ölümündən sonra şəhər Səlahəddin Əyyubiyə keçdi.", "a20855b8"]},
"OLAYLAR_T5_1000B:1175-07-22:0":{"b": ["Əyyubilər Ədəni aldı, Züreyilər sona çatdı", "d253acf0"], "d": ["Əyyubilər Ədənə irəliləyib vəzir Yasir b. Bilalı edam etdilər.", "06e4a877"]},
"OLAYLAR_T5_1000B:1176-09-17:0":{"b": ["Miryokefalondan sonra Bizans Dorylaionu boşaltdı", "24aef255"], "d": ["Miryokefalon məğlubiyyətindən sonra Manuel müqaviləyə əsasən Dorylaion istehkamını dağıdıb şəhəri boşaltdı; Türklər bura Eskişehir deməyə başladı.", "d56a7724"]},
"OLAYLAR_T5_1000B:1178-01-01:0":{"b": ["Amasya Səlcuq torpaqlarına qatıldı", "cf56b964"], "d": ["II Qılıcarslan Danişməndli torpaqlarını (Amasya daxil) Səlcuq ölkəsinə qatdı.", "ddbb98aa"]},
"OLAYLAR_T5_1000B:1187-01-01:0":{"b": ["Asen qardaşları Şimali Bolqarıstanı aldı; Bizans II Bolqar Dövlətini tanıdı", "ff0554e9"], "d": ["Petar və Asen qardaşları Kuman dəstəyi ilə Şimali Bolqarıstanı yenidən aldı; 1187 sülhü ilə Bizans II Bolqar Dövlətini tanıdı.", "fc165cbf"]},
