"OLAYLAR_T5_1000B:1235-01-01:0":{"b": ["İznik İmperatoru Vatatzis Geliboluyu geri aldı", "a6936e33"], "d": ["İznik İmperatoru III İoannis Vatatzis Geliboluyu Latınlardan geri aldı (1235).", "184a089e"]},
"OLAYLAR_T5_1000B:1243-07-01:0":{"b": ["Monqollar Amasyanı zəbt etdi", "783bcd0c"], "d": ["Kösədağdan sonra Monqollar şəhəri aldı, Monqol valiləri idarə etdi.", "4e46e2df"]},
"OLAYLAR_T5_1000B:1246-01-01:0":{"b": ["Vatatzis Trakiyaya keçdi: Ədirnə və Salonik İznik İmperatorluğuna qatıldı", "0bf61ca5"], "d": ["İznik hökmdarı III İoannis Vatatzis 1246-da Trakiyaya keçərək Bolqarların işğal etdiyi torpaqları və Saloniki ələ keçirdi.", "73992921"]},
"OLAYLAR_T5_1000B:1250-01-01:0":{"b": ["Rəsuli hakimiyyəti Məkkədə tanınırdı — Nurəddin Ömər sui-qəsdin qurbanı oldu", "d7e03c21"], "d": ["Yəmən Rəsuli Sultanı Nurəddin Ömər Cəneddə öldürüləndə (Fevral 1250) dövlətinin hakimiyyəti Məkkə ilə Hədramut arasında tanınırdı; Əyyubi sultanlığının sona çatdığı il Məkkə Rəsuli suzerenliyində görünür.", "ba654624"]},
"OLAYLAR_T5_1000B:1250-04-30:0":{"b": ["Misirdə Məmlük Dövləti quruldu — İsgəndəriyyə, Mənsurə və Feyyum Məmlüklərə keçdi", "230c1a11"], "d": ["Turanşahdan sonra Şəcərüddür və İzzəddin Aybək ilə Məmlük hakimiyyəti quruldu; Misir şəhərləri (İsgəndəriyyə, Mənsurə, Feyyum) Məmlük idarəsinə keçdi. Mənbə Aybəkin taxta çıxışını 3 iyul 1250 verir; atlas günü Əyyubi künyəsinin bitişindən (30 aprel 1250) götürdü — künyə günü mənbə deyil, fərq bildirildi.", "f9743bcd"]},
"OLAYLAR_T5_1000B:1250-04-30:1":{"b": ["Hələb Əyyubisi ən-Nasir Yusif Dəməşqə hakim oldu", "d585985d"], "d": ["Misirdə Məmlük hakimiyyəti qurularkən Hələb hakimi ən-Nasir Yusif Dəməşqi aldı (648/1250).", "c05ddddc"]},
"OLAYLAR_T5_1000B:1253-04-01:0":{"b": ["Qüds sülhlə Məmlüklərə buraxıldı", "50d53fac"], "d": ["Xəlifənin vasitəçiliyi ilə bağlanan sülhlə Qüds Məmlüklərə buraxıldı.", "82982e3a"]},
"OLAYLAR_T5_1000B:1256-01-01:0":{"b": ["Qüds yenidən Əyyubilərə keçdi", "fdeedd4a"], "d": ["Fələstin və Qüds təkrar Suriya Əyyubilərinin əlinə keçdi.", "46a6e2a9"]},
"OLAYLAR_T5_1000B:1260-03-01:0":{"b": ["Monqollar Dəməşqi aldı", "430bdfea"], "d": ["Hülakunun Suriya yürüşündə Dəməşq Monqollara keçdi.", "407e5d3f"]},
"OLAYLAR_T5_1000B:1260-09-03:0":{"b": ["Eynicalut döyüşü: Dəməşq və Qüds Məmlüklərə keçdi", "40ebd7b7"], "d": ["Qutuz Monqolları Eynicalutda məğlub etdi (25 Ramazan 658 / 3 sentyabr 1260); Suriyanın böyük hissəsi, Dəməşq və Qüds Məmlüklərin əlinə keçdi, Əyyubi sülaləsi sona çatdı.", "619c8015"]},
"OLAYLAR_T5_1000B:1261-06-09:0":{"b": ["Baybars Abbasi xilafətini Qahirədə dirçəltdi — Məkkə və Mədinə Məmlüklərə bağlandı", "a5128a1e"], "d": ["Baybars, Bağdadın yıxılmasından xilas olan Abbasi Əhmədi Qahirədə xəlifə elan edib beyət etdi; xilafətin hamisi sifəti ilə Həremeyni də Məmlük suzerenliyinə bağladı. Gün xilafətin dirçəldilməsinin günüdür; Məkkə və Mədinənin bağlanma günü mənbədə yoxdur (aşağı sərhəd).", "638d550a"]},
"OLAYLAR_T5_1000B:1261-07-25:0":{"b": ["İznik birlikləri İstanbula daxil oldu — Bizans İmperatorluğu yenidən quruldu", "81741490"], "d": ["İznik birlikləri 25 iyul 1261-də İstanbula girərək Latın hakimiyyətinə son verdi; Laskaris (İznik) dövlətinin torpaqları — Bursa, İzmir, Çimpe, Ədirnə, Salonik — yenidən Bizans İmperatorluğu oldu. Atlas bu nöqtələrdə 1261-dən əvvəlki İznik İmperatorluğu dövrünü yalnız mənbədə adı ilə keçənlərdə göstərir.", "b389b508"]},
"OLAYLAR_T5_1000B:1271-01-01:0":{"b": ["Charles d’Anjou Dürrəs və Kruyanı aldı", "082a86b8"], "d": ["Anjou sülaləsindən Charles 1271-1272-də Dürrəs ilə Kruyanı alıb köhnə qalanı yenidən tikdirdi.", "e9f84d14"]},
"OLAYLAR_T5_1000B:1284-01-01:0":{"b": ["Siciliyalılar Cərbə adasını işğal etdi", "daab5ad2"], "d": ["Cərbə adası 683 (1284-85) ilində Siciliyalılar tərəfindən işğal edildi; əvvəl papalığın mülkü, sonra Sisiliya Krallığına bağlı oldu.", "691035b3"]},
"OLAYLAR_T5_1000B:1318-01-01:0":{"b": ["Yanya yenidən Bizans İmperatorluğuna qatıldı", "60016303"], "d": ["XIII əsrin ikinci yarısında bir çox dəfə əldən-ələ keçən Yanya 1318-də yenidən Bizansa qatıldı, lakin müəyyən dərəcədə özünüidarəsini qoruyub saxladı; Epir Despotluğunun mərkəzi Artaya keçdi.", "14c24d12"]},
"OLAYLAR_T5_1000B:1334-01-01:0":{"b": ["Cərbə əhalisi Siciliyalıları adadan qovdu", "ff71985e"], "d": ["Sisiliya valilərinin pis idarəçiliyinə qarşı üsyan edən ada əhalisi 1334-də Siciliyalıları qovdu; Cərbə yenidən Həfsi idarəsinə girdi.", "1ddb9780"]},
"OLAYLAR_T5_1000B:1363-01-01:0":{"b": ["Charles Thopia Kruyaya hakim oldu", "4e40583d"], "d": ["Çar Duşanın ölümündən (1355) sonra Alban Charles Thopia Kruyaya hakim oldu.", "7af64cd2"]}
